		value: ''
	})
	.finish();

/**
 * @param {CursorEvent} event
 */
export function cursorClick(event) {
	const key = scriptProperties.propKey?.trim();
	if (!key) {
		console.error('[SALB] "User Property Key" cannot be empty.');
		return;
	}

	const hasProp = Object.prototype.hasOwnProperty.call(engine.userProperties, key);
	if (!hasProp) {
		console.error(`[SALB] user property '${key}' not found.`);
		return;
	}

	engine.openUserShortcut(key);
}

