var mediaState = MediaPlaybackEvent.PLAYBACK_STOPPED;

export function mediaPlaybackChanged(event) {
    mediaState = event.state;
}

export function update() {
    if (mediaState === MediaPlaybackEvent.PLAYBACK_PLAYING || mediaState === MediaPlaybackEvent.PLAYBACK_PAUSED) {
        return thisLayer.visible = true;
    } else if (mediaState === MediaPlaybackEvent.PLAYBACK_STOPPED) {
        return thisLayer.visible = false;
    }
    return;
}

