'use strict';
// Please note: Do not remove this line or asset references may break.
export let __workshopId = '3626180981';

import * as WEMath from 'WEMath';

export var scriptProperties = createScriptProperties()
    .addSlider({
        name: 'hoverScale',
        label: 'Hover Scale',
        value: 0.4,
        min: 1,
        max: 2,
        integer: false
    })
    .addSlider({
        name: 'clickScale',
        label: 'Click Scale',
        value: 0.25,
        min: 0.5,
        max: 2,
        integer: false
    })
    .addSlider({
        name: 'speed',
        label: 'Animation Speed',
        value: 5,
        min: 0.1,
        max: 10,
        integer: false
    })
    .finish();

let targetScale = new Vec3(0.35, 0.35, 0.35); // Default scale
let currentScale = new Vec3(0.35, 0.35, 0.35);
let isHovered = false;
let isClicked = false;

/**
 * @param {Vec3} value - for property 'scale'
 * @return {Vec3} - update current property value
 */
export function update(value) {
    let frametime = engine.frametime * scriptProperties.speed;

    // Smoothly transition to the target scale
    currentScale = currentScale.mix(targetScale, frametime);

    return currentScale;
}

/**
 * @param {CursorEvent} event
 * Triggers when the cursor enters the layer's bounding box
 */
export function cursorEnter(event) {
    isHovered = true;
    if (!isClicked) {
        targetScale = new Vec3(scriptProperties.hoverScale, scriptProperties.hoverScale, 1);
    }
}

/**
