    if (startPos && endPos) {
        // 确保进度比例在0-1范围内
        let progress = Math.max(0, Math.min(1, curRatio));

        // 只在X轴上进行线性插值，Y轴保持不变
        value.x = startPos.x + (endPos.x - startPos.x) * progress;
