export let __workshopId = '3626180981';

var ofg = 0;

export function mediaPlaybackChanged(event) {
    if (event.state == 0 || event.state == 2) {
        ofg = 0; // Play
    } else if (event.state == 1) {
        ofg = 1; // Pause
    }
}

export function update(value) {
    if (ofg == 0) {
        thisScene.getLayer('PlayerPlayBold21').visible = true;
        thisScene.getLayer('PlayerPauseBold21').visible = false;
