    .addSlider({
        name: 'hoverScale',
        label: 'Hover Scale',
        value: 0.4,
        min: 1,
        max: 2,
        integer: false
    })
    .addSlider({
        name: 'clickScale',
        label: 'Click Scale',
        value: 0.25,
        min: 0.5,
        max: 1,
        integer: false
    })
