export var scriptProperties = createScriptProperties()
    .addCheckbox({ name: 'isMovable', label: 'Is Movable / Arrastrar y mover', value: false })
    .addText({ name: 'targetLayerName', label: 'Destination layer name / Nombre de la capa de destino', value: '' })
    .addText({ name: 'storageKey', label: 'Local storage key name / Nombre de la clave de almacenamiento local', value: 'DragPosition' })
.finish();

// variables relacionadas con el arrastre
let isDragging = false;
let dragOffset;
let targetLayer;

export function init() {
    // Obtener la capa de destino
    if (scriptProperties.targetLayerName && scriptProperties.targetLayerName.trim() !== '') {
        targetLayer = thisScene.getLayer(scriptProperties.targetLayerName.trim());
    } else {
        targetLayer = thisLayer; // Si no se ha especificado una capa de destino, se utilizará la capa actual
    }

    // Cargar la posición desde el almacenamiento local
    let storageKey = scriptProperties.storageKey || 'DragPosition';
    let storedPosition = localStorage.get(storageKey);
    if (storedPosition && targetLayer) {
        targetLayer.origin = storedPosition;
    }
}

export function cursorDown(event) {
    if (scriptProperties.isMovable && targetLayer) {
        isDragging = true;
        dragOffset = targetLayer.origin.subtract(event.worldPosition);
    }
}

export function cursorUp(event) {
    if (isDragging && targetLayer) {
        isDragging = false;
        // Guardar la posición en el almacenamiento local
        let storageKey = scriptProperties.storageKey || 'DragPosition';
        localStorage.set(storageKey, targetLayer.origin);
    }
}

export function cursorMove(event) {
    if (isDragging && scriptProperties.isMovable && targetLayer) {
        let newPos = event.worldPosition.add(dragOffset);
        targetLayer.origin = newPos;
    }
}
// Seyul.Saltz

