// Capas
let durationLayer;   // durationsong4
let remainingLayer;  // timerestar4

// Variables
let totalTime = 0;
let currentTime = 0;

// Formateo MM:SS
function format(sec) {
    if (!sec || sec < 0) sec = 0;
    let m = Math.floor(sec / 60);
    let s = Math.floor(sec % 60);
    return (m < 10 ? "0" + m : m) + ":" + (s < 10 ? "0" + s : s);
}

// Mostrar duración total
function updateDuration() {
    durationLayer.text = totalTime > 0 ? format(totalTime) : "--:--";
}

// Mostrar tiempo restante (con "-")
function updateRemaining() {
    let remain = totalTime - currentTime;
    remainingLayer.text = remain > 0 ? "-" + format(remain) : "-00:00";
}

// Llamado por Wallpaper Engine
export function init() {
    durationLayer = thisScene.getLayer("durationsong4");
    remainingLayer = thisScene.getLayer("timerestar4");

    durationLayer.text = "--:--";
    remainingLayer.text = "-00:00";
}

// Para AudioLayers internos (.mp3)
export function update() {
    currentTime += engine.frametime;
    updateRemaining();
}

// Media Integration: timeline
export function mediaTimelineChanged(event) {
    totalTime = event.duration;
    currentTime = event.position;

    updateDuration();
    updateRemaining();
}

// Media Integration: propiedades
export function mediaPropertiesChanged(event) {
    if (event.duration != null) {
        totalTime = event.duration;
        updateDuration();
    }
}

