import * as WEMath from 'WEMath';

export var scriptProperties = createScriptProperties()
    .addCheckbox({
        name: 'enableScale',
        label: 'Enable Zoom When Hovering The Cursor // Habilitar zoom al pasar el cursor',
        value: true
    })
    .addSlider({
        name: 'hoScale',
        label: 'Hover over scale multiplier',
        value: 1.5,
        min: 0.1,
        max: 2,
        integer: false
    })
    .addSlider({
        name: 'speed',
        label: 'Scale change speed',
        value: 10,
        min: 1,
        max: 100,
        integer: false
    })
    .finish();

let initScale, newScale, hover = false, propertyCheck = true, speed;

export function update(value) {

    // ❌ Si el checkbox está apagado → no hay efecto
    if (!scriptProperties.enableScale) {
        return value;
    }

    // ✔ Hover activo
    if (hover) {
        value = new Vec3(
            WEMath.mix(value.x, newScale.x, speed),
            WEMath.mix(value.y, newScale.y, speed),
            WEMath.mix(value.z, newScale.z, speed)
        );
    }
    // ✔ Hover desactivado → vuelve al tamaño original
    else {
        value = new Vec3(
            WEMath.mix(value.x, initScale.x, speed),
            WEMath.mix(value.y, initScale.y, speed),
            WEMath.mix(value.z, initScale.z, speed)
        );
    }

    return value;
}

export function init(value) {
    initScale = value;
    return value;
}

export function cursorEnter(event) {
    if (scriptProperties.enableScale) hover = true;
}

export function cursorLeave(event) {
    hover = false;
}

export function applyUserProperties(changedUserProperties) {

    if (!scriptProperties.enableScale) return;

    if (scriptProperties.hoScale != undefined && propertyCheck) {
        newScale = new Vec3(initScale.multiply(scriptProperties.hoScale));
        speed = scriptProperties.speed / 100;
        propertyCheck = false;
    }
}

'use strict';
// Please note: Do not remove this line or asset references may break.
export let __workshopId = '3624642656';
// Please note: Do not remove this line or asset references may break.
// Please note: Do not remove this line or asset references may break.

/**
 * 媒体进度条动态缩放脚本
 * 根据媒体播放进度动态调整图层的X轴缩放，实现进度条效果
 * 优化版本：减少频繁事件调用，添加范围限制，提高播放器兼容性
 */

// 全局变量定义
let defScale;        // 默认缩放值，存储初始缩放状态
let defRatio = 0.01; // 默认比例，当无法获取媒体时长时使用
let curRatio = 0;    // 当前播放进度比例 (0-1)
let playbackState;   // 媒体播放状态
let oldTime = 0;     // 上次更新的时间戳
let newTime = 0;     // 当前时间戳
let maxScale = 1.0;  // 最大缩放限制，防止进度条超出范围
let mediaDuration = 0;   // 媒体总时长
let mediaPosition = 0;   // 当前播放位置
let isMediaInfoValid = false; // 媒体信息是否有效

/**
 * 更新频率倍数
 * 控制进度条更新的频率
 * 1.0 = 每秒更新一次，0.75 = 每0.75秒更新一次
 * 数值越小准确性越低，建议不低于0.5，1.0可达到100%准确性
 */
const updateMult = 0.75;

/**
 * 主更新函数 - 每帧调用
 * 根据媒体播放状态和时间间隔更新图层缩放
 * 优化版本：添加范围限制和错误处理
 * 
 * @param {Object} value - 当前图层的缩放值对象 {x, y}
 * @return {Object} - 更新后的缩放值
 */
export function update(value) {
    newTime = Date.now(); // 获取当前时间戳

    // 无论什么情况，都要根据当前进度比例更新X轴缩放
    // 这确保了歌曲切换时进度条能立即清零
    const targetScale = defScale.x * curRatio;
    value.x = Math.min(targetScale, defScale.x * maxScale);

    // 检查媒体是否正在播放且达到更新间隔
    if (playbackState == MediaPlaybackEvent.PLAYBACK_PLAYING && 
        newTime - oldTime >= 1000 * updateMult) {

        // 如果有有效的媒体信息，使用精确的进度计算
        if (isMediaInfoValid && mediaDuration > 0) {
            // 根据时间间隔增加播放位置
            mediaPosition += updateMult;
            // 计算精确的进度比例
            curRatio = Math.min(mediaPosition / mediaDuration, 1.0);
        } else {
            // 回退到估算模式
            curRatio += defRatio * updateMult;
        }

        // 应用最大范围限制，防止进度条超出范围
        curRatio = Math.min(curRatio, 1.0);

        // 更新时间戳
        oldTime = newTime;
    }

    return value;
}

/**
 * 初始化函数 - 脚本启动时调用
 * 设置初始状态和默认值
 * 
 * @param {Object} value - 初始缩放值对象 {x, y}
 * @return {Object} - 返回初始缩放值
 */
export function init(value) {
    defScale = value;                                    // 保存默认缩放值
    oldTime = Date.now();                               // 初始化时间戳
    playbackState = MediaPlaybackEvent.PLAYBACK_STOPPED; // 设置初始播放状态为停止
    curRatio = 0;                                       // 重置进度比例
    isMediaInfoValid = false;                           // 重置媒体信息状态
    return value;
}

/**
 * 媒体属性变化事件处理 - 专门用于检测歌曲切换
 * 当歌曲、艺术家、专辑等媒体属性发生变化时调用
 * 这是检测歌曲切换的最佳事件
 * 
 * @param {Object} event - 媒体属性事件对象
 */
export function mediaPropertiesChanged(event) {
    // 歌曲切换时立即重置进度条为0
    curRatio = 0;
    mediaPosition = 0;
    isMediaInfoValid = false;

    // 重置时间戳，确保下次播放时能正确更新
    oldTime = Date.now();
}

/**
 * 媒体时间轴变化事件处理（简化版本）
 * 仅用于获取媒体时长和位置信息，不处理歌曲切换
 * 
 * @param {Object} event - 媒体时间轴事件对象
 * @param {Number} event.duration - 媒体总时长（秒）
 * @param {Number} event.position - 当前播放位置（秒）
 */
export function mediaTimelineChanged(event) {
    // 仅在媒体信息发生重大变化时更新
    if (event.duration && event.duration > 0) {
        // 更新媒体信息
        mediaDuration = event.duration;              // 保存媒体总时长
        mediaPosition = event.position || 0;         // 保存当前播放位置
        defRatio = 1 / event.duration;              // 计算每秒对应的进度比例
        curRatio = mediaPosition / mediaDuration;    // 计算当前播放进度比例
        isMediaInfoValid = true;                    // 标记媒体信息有效
    }
}

/**
 * 媒体播放状态变化事件处理（简化版本）
 * 当媒体开始播放、暂停或停止时调用
 * 歌曲切换检测已移至 mediaPropertiesChanged 函数
 * 
 * @param {Object} event - 媒体播放状态事件对象
 * @param {Number} event.state - 播放状态（PLAYBACK_PLAYING/PLAYBACK_PAUSED/PLAYBACK_STOPPED）
 */
export function mediaPlaybackChanged(event) {
    playbackState = event.state; // 更新播放状态

    // 根据播放状态执行相应操作
    switch (event.state) {
        case MediaPlaybackEvent.PLAYBACK_PLAYING:
            // 开始播放时，重置时间戳
            oldTime = Date.now();

            // 如果事件包含媒体信息，更新相关数据
            if (event.duration && event.duration > 0) {
                mediaDuration = event.duration;
                mediaPosition = event.position || 0;
                defRatio = 1 / event.duration;
                curRatio = mediaPosition / mediaDuration;
                isMediaInfoValid = true;
            }
            break;

        case MediaPlaybackEvent.PLAYBACK_PAUSED:
            // 暂停时保持当前状态，不重置进度
            break;

        case MediaPlaybackEvent.PLAYBACK_STOPPED:
            // 停止时重置进度
            curRatio = 0;
            mediaPosition = 0;
            isMediaInfoValid = false;
            break;
    }
}

