'use strict';
// Please note: Do not remove this line or asset references may break.
export let __workshopId = '3624642656';
// Please note: Do not remove this line or asset references may break.
// Please note: Do not remove this line or asset references may break.
// Please note: Do not remove this line or asset references may break.

import * as WEMath from 'WEMath';

export var scriptProperties = createScriptProperties()
    .addSlider({
        name: 'triggerDistance',
        label: 'Trigger Distance (pixels)',
        value: 300,
        min: 50,
        max: 1000,
        integer: true
    })
    .addSlider({
        name: 'hiddenOpacity',
        label: 'Hidden Opacity',
        value: 0.0,
        min: 0.0,
        max: 1.0,
        integer: false
    })
    .addSlider({
        name: 'visibleOpacity',
        label: 'Visible Opacity',
        value: 1.0,
        min: 0.0,
        max: 1.0,
        integer: false
    })
    .addSlider({
        name: 'animationSpeed',
        label: 'Animation Speed',
        value: 2.0,
        min: 0.1,
        max: 10.0,
        integer: false
    })
    .finish();

let isMediaPlaying = false;

/**
 * Código universal para la interacción del mouse con múltiples subniveles
 * Adecuado para varias capas hijas, por ejemplo, cápsulas 1-10
 * Cada capa hija puede responder individualmente a la distancia del ratón según su posición
 * 
 * @param {Number} value - para la propiedad que controlas (opacidad)
 * @return {Number} - actualizar el valor actual de la propiedad
 */
export function update(value) {
    // Comprobación de seguridad: asegurarse de que todos los objetos necesarios estén inicializados
    if (!input || !input.cursorWorldPosition || !thisLayer) {
        return value; // devuelve el valor actual para evitar parpadeos
    }

    // Obtener la posición mundial del ratón
    const mousePos = input.cursorWorldPosition;

    let distance;
    let currentLayerWorldX, currentLayerWorldY;

    // Comprobar si la capa actual tiene un padre
    const parentLayer = thisLayer.getParent();

    if (parentLayer) {
        // Si es una capa hija: calcular la posición real en el mundo de la capa hija actual
        // Hay que considerar el factor de escala del padre
        const parentCenter = parentLayer.origin;
        const parentScale = parentLayer.scale;
        const childRelativePos = thisLayer.origin;

        // Posición real en el mundo de la capa hija = posición mundial del padre + (posición relativa de la hija * escala del padre)
        currentLayerWorldX = parentCenter.x + (childRelativePos.x * parentScale.x);
        currentLayerWorldY = parentCenter.y + (childRelativePos.y * parentScale.y);

        // Calcular la distancia del ratón a la posición real en el mundo de la capa hija actual
        const deltaX = mousePos.x - currentLayerWorldX;
        const deltaY = mousePos.y - currentLayerWorldY;
        distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);

        // Información de depuración opcional (puede comentarse para mejorar el rendimiento)
        // console.log(thisLayer.name + ' - posición mundial:', currentLayerWorldX + ',' + currentLayerWorldY + ', distancia:', Math.round(distance));
    } else {
        // Si es una capa independiente: usar directamente el punto central de la capa
        const layerCenter = thisLayer.origin;
        currentLayerWorldX = layerCenter.x;
        currentLayerWorldY = layerCenter.y;

        const deltaX = mousePos.x - currentLayerWorldX;
        const deltaY = mousePos.y - currentLayerWorldY;
        distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    }

    // Obtener la distancia de activación y los valores de opacidad configurados
    const triggerDistance = scriptProperties.triggerDistance;
    const hiddenOpacity = scriptProperties.hiddenOpacity;
    const visibleOpacity = scriptProperties.visibleOpacity;
    const animationSpeed = scriptProperties.animationSpeed;

    // Determinar si el ratón está dentro del rango de activación
    const isMouseInRange = distance <= triggerDistance;

    // Determinar la opacidad objetivo
    let targetOpacity;
    if (isMouseInRange) {
        // El ratón está dentro del rango, el objetivo es opacidad visible
        targetOpacity = visibleOpacity;
    } else {
        // El ratón está fuera del rango, el objetivo es opacidad oculta
        targetOpacity = hiddenOpacity;
    }

    // Comprobar si está activada la función de desvanecimiento con medios
    const fadeEnabled = shared.fadeWithMedia || false;
    if (fadeEnabled && isMediaPlaying) {
        targetOpacity = hiddenOpacity;
    }

    // Usar engine.frametime para una transición animada basada en tiempo
    const deltaTime = engine.frametime;
    const changeRate = animationSpeed * deltaTime;

    let currentOpacity;
    if (value < targetOpacity) {
        // Necesita aumentar opacidad (mostrar)
        currentOpacity = Math.min(value + changeRate, targetOpacity);
    } else if (value > targetOpacity) {
        // Necesita reducir opacidad (ocultar)
        currentOpacity = Math.max(value - changeRate, targetOpacity);
    } else {
        // Ya se alcanzó el valor objetivo
        currentOpacity = targetOpacity;
    }

    // Asegurar que el valor retornado esté en el rango válido (0-1)
    return Math.max(0, Math.min(1, currentOpacity));
}

/**
 * @param {MediaPlaybackEvent} event
 * Maneja los cambios en la reproducción de medios para actualizar el estado de reproducción.
 */
export function mediaPlaybackChanged(event) {
    isMediaPlaying = (event.state === MediaPlaybackEvent.PLAYBACK_PLAYING);
}

